<section class="page-hero section-shell"><p class="eyebrow">Course catalogue</p><h1>Find a practical place to begin.</h1><p>Search a growing set of structured lessons in programming, web development, and project-based learning.</p></section>
<section class="section-shell"><form class="catalogue-filter" method="get" action="index.php"><input type="hidden" name="page" value="courses"><label><span class="sr-only">Search courses</span><input name="q" type="search" value="<?= e($filters['q']) ?>" placeholder="Search courses"></label><label><span class="sr-only">Difficulty</span><select name="level"><option value="">All levels</option><?php foreach (['beginner','intermediate','advanced'] as $level): ?><option value="<?= $level ?>" <?= $filters['level'] === $level ? 'selected' : '' ?>><?= ucfirst($level) ?></option><?php endforeach; ?></select></label><label><span class="sr-only">Category</span><select name="category"><option value="">All categories</option><?php foreach ($categories as $category): ?><option value="<?= e($category) ?>" <?= $filters['category'] === $category ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select></label><label><span class="sr-only">Sort courses</span><select name="sort"><option value="newest" <?= $filters['sort'] === 'newest' ? 'selected' : '' ?>>Newest</option><option value="title" <?= $filters['sort'] === 'title' ? 'selected' : '' ?>>Title A–Z</option><option value="duration" <?= $filters['sort'] === 'duration' ? 'selected' : '' ?>>Shortest first</option></select></label><button class="button" type="submit">Apply</button></form></section>
<section class="section-shell course-grid catalogue-grid"><?php if (!$courses): ?><div class="empty-card"><h2>No courses matched that search.</h2><p>Try a different keyword or clear a filter.</p><a class="button button-outline" href="<?= route('courses') ?>">Clear filters</a></div><?php endif; ?><?php foreach ($courses as $course): ?><article class="course-card"><div class="course-art course-art-<?= e($course['category'] === 'Programming' ? 'java' : 'web') ?>"><span><?= $course['category'] === 'Programming' ? '☕' : '&lt;/&gt;' ?></span></div><div class="course-card-copy"><div class="tag-row"><span class="tag"><?= e($course['difficulty']) ?></span><span><?= e($course['category']) ?></span></div><h2><?= e($course['title']) ?></h2><p><?= e($course['short_description']) ?></p><footer><span><?= (int) $course['lesson_count'] ?> lessons · <?= (int) $course['estimated_minutes'] ?> min</span><a href="<?= route('course', ['slug' => $course['slug']]) ?>">View course →</a></footer></div></article><?php endforeach; ?></section>
